declare(strict_types=1);
function gszPageStart(string $title):void {echo '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'.e($title).' · GSZ</title><link rel="stylesheet" href="assets.css"><link rel="stylesheet" href="planning.css"></head><body><main><header><a href="index.php">Zentrale</a><a href="planner.php">Heute</a><a href="customers.php">Kunden</a><a href="appointments.php">Termine</a><a href="mail.php">E-Mail</a><a href="bank.php">Bank</a><a href="accounting.php">Buchhaltung</a><a href="receivables.php">Offene Posten</a><a href="finance_recurrences.php">Finanzvorlagen</a><a href="cash_assets.php">Kasse / Anlagen</a><a href="documents.php">Dokumente</a><a href="estate.php">Meine Immobilien</a><a href="system_check.php">Systemcheck</a></header><h1>'.e($title).'</h1>';if(isset($_SESSION['app_error'])){echo '<p class="error" role="alert">'.e($_SESSION['app_error']).'</p>';unset($_SESSION['app_error']);}if(isset($_SESSION['app_notice'])){echo '<p role="status">'.e($_SESSION['app_notice']).'</p>';unset($_SESSION['app_notice']);}}
function gszPageEnd():void{echo '</main></body></html>';}
function gszFields(string $action):void{echo '<input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'">';}
function gszUiError(Throwable $e):void{$_SESSION['app_error']=$e instanceof PDOException?'Datenbank nicht bereit. Migrationen und Betriebsstatus prüfen.':$e->getMessage();}
